        "quote": "如果超过12小时还没打，先补今天该用的那一针"
      },
      {
        "event_id": "lite_evt_00046",
        "explanation": "Later actionability was strong, with immediate obstetric emergency escalation.",
        "quote": "现在立刻去最近的产科急诊/胎监室"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00046",
        "explanation": "The doctor correctly recognized reduced fetal movement as an emergency requiring obstetric fetal monitoring.",
        "quote": "胎动明显减少已经是急症信号"
      },
      {
        "event_id": "lite_evt_00091",
        "explanation": "The doctor appropriately avoided equating an abnormal but not immediately operative status with fetal safety.",
        "quote": "不是“已经安全”"
      }
    ],
    "continuity_memory_focus": [
      {
