        "quote": "医生登记结果追踪/回访任务"
      },
      {
        "event_id": "lite_evt_02394",
        "explanation": "The doctor maintained the inpatient monitoring boundary and avoided repeated low-value report chasing.",
        "quote": "线上端暂时没有新数据可核对"
      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00016",
        "explanation": "The anticoagulation advice created a serious safety risk despite later mitigation.",
        "quote": "先补今天该用的那一针"
      },
      {
        "event_id": "lite_evt_00046",
        "explanation": "The doctor later warned against self-supplementing enoxaparin and routed dose decisions to onsite clinicians.",
        "quote": "克赛先别自行补打"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00377",
        "explanation": "The doctor gave the patient language to explain the risk to her husband and maintain adherence to inpatient monitoring.",
        "quote": "给老公一句简单解释"
      },
      {
        "event_id": "lite_evt_00046",
        "explanation": "The plan addressed transport and document barriers by telling her what to bring and where to go.",
        "quote": "把整盒药、处方单、之前B超一起带去"
      }
    ]
  },
